// Validation des paramètres d'entrée
const input = $input.first().json;

const melPath = input.mel_path || input.body?.mel_path;
const mmelPath = input.mmel_path || input.body?.mmel_path;
const apiKey = input.api_key || input.body?.api_key || $env.MISTRAL_API_KEY || '';

if (!melPath || !mmelPath) {
  throw new Error('mel_path and mmel_path are required');
}

return {
  json: {
    mel_path: melPath,
    mmel_path: mmelPath,
    api_key: apiKey,
    run_id: new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14),
    started_at: new Date().toISOString()
  }
};

// Consolider les résultats du parsing
const melResult = $('Parse MEL Document').first().json;
const mmelResult = $('Parse MMEL Document').first().json;
const config = $('Validate Input').first().json;

return {
  json: {
    run_id: config.run_id,
    mel_items: melResult.items || [],
    mmel_items: mmelResult.items || [],
    mel_count: melResult.items_count || melResult.items?.length || 0,
    mmel_count: mmelResult.items_count || mmelResult.items?.length || 0,
    api_key: config.api_key,
    parsing_completed_at: new Date().toISOString()
  }
};

// Indexation et matching MEL/MMEL
const data = $input.first().json;
const melItems = data.mel_items;
const mmelItems = data.mmel_items;

// Créer un index MMEL
const mmelIndex = {};
for (const item of mmelItems) {
  const key = `${item.ata_chapter}|${item.item_number}`;
  mmelIndex[key] = item;
}

// Matcher chaque item MEL
const matches = [];
const matchedMmelKeys = new Set();

for (const melItem of melItems) {
  const key = `${melItem.ata_chapter}|${melItem.item_number}`;
  const mmelItem = mmelIndex[key];

  if (mmelItem) {
    matches.push({
      mel_item_id: key,
      mmel_item_id: key,
      exact_match: true,
      match_type: 'exact',
      match_confidence: 'high'
    });
    matchedMmelKeys.add(key);
  } else {
    matches.push({
      mel_item_id: key,
      mmel_item_id: null,
      exact_match: false,
      match_type: 'none',
      match_confidence: 'no_match',
      requires_hitl_review: true,
      hitl_reason: 'No matching MMEL item found'
    });
  }
}

// Items MMEL non matchés
const unmatchedMmel = Object.keys(mmelIndex).filter(k => !matchedMmelKeys.has(k));

return {
  json: {
    ...data,
    matches: matches,
    matched_count: matches.filter(m => m.exact_match).length,
    unmatched_mel: matches.filter(m => !m.exact_match).length,
    unmatched_mmel: unmatchedMmel.length,
    unmatched_mmel_keys: unmatchedMmel,
    indexing_completed_at: new Date().toISOString()
  }
};

// Comparaison MEL/MMEL et génération des verdicts
const data = $input.first().json;
const melItems = data.mel_items;
const mmelItems = data.mmel_items;
const matches = data.matches;

// Index MMEL
const mmelIndex = {};
for (const item of mmelItems) {
  const key = `${item.ata_chapter}|${item.item_number}`;
  mmelIndex[key] = item;
}

// Index MEL
const melIndex = {};
for (const item of melItems) {
  const key = `${item.ata_chapter}|${item.item_number}`;
  melIndex[key] = item;
}

// Hiérarchie des catégories (1 = plus restrictif)
const categoryRank = { 'A': 1, 'B': 2, 'C': 3, 'D': 4, '-': 5, '': 5 };

const comparisons = [];
const stats = {
  compliant: 0,
  more_restrictive: 0,
  less_restrictive: 0,
  missing_in_mel: 0,
  missing_in_mmel: 0,
  category_mismatch: 0,
  critical: 0,
  high: 0,
  medium: 0,
  warning: 0,
  info: 0,
  hitl_required: 0
};

// Comparer les items matchés
for (const match of matches) {
  const melItem = melIndex[match.mel_item_id];
  const mmelItem = mmelIndex[match.mmel_item_id];

  if (!mmelItem) {
    // Item MEL sans équivalent MMEL
    comparisons.push({
      mel_item_id: match.mel_item_id,
      mmel_item_id: null,
      ata_chapter: melItem?.ata_chapter || '',
      item_number: melItem?.item_number || '',
      item_description: melItem?.item_description || '',
      verdict: 'MISSING_IN_MMEL',
      severity: 'info',
      mel_category: melItem?.category || '',
      mmel_category: '',
      mel_remarks: melItem?.remarks || '',
      mmel_remarks: ''
    });
    stats.missing_in_mmel++;
    stats.info++;
    continue;
  }

  // Comparer les catégories
  const melCat = (melItem?.category || '').toUpperCase();
  const mmelCat = (mmelItem?.category || '').toUpperCase();
  const melRank = categoryRank[melCat] || 5;
  const mmelRank = categoryRank[mmelCat] || 5;

  let verdict, severity;
  let requiresHitl = false;
  let hitlReason = '';

  if (melRank === mmelRank) {
    verdict = 'COMPLIANT';
    severity = 'info';
    stats.compliant++;
    stats.info++;
  } else if (melRank < mmelRank) {
    verdict = 'MORE_RESTRICTIVE';
    severity = 'info';
    stats.more_restrictive++;
    stats.info++;
  } else {
    verdict = 'LESS_RESTRICTIVE';
    severity = 'critical';
    stats.less_restrictive++;
    stats.critical++;
    requiresHitl = true;
    hitlReason = `CRITICAL: MEL category ${melCat} is less restrictive than MMEL ${mmelCat}`;
  }

  if (requiresHitl) stats.hitl_required++;

  comparisons.push({
    mel_item_id: match.mel_item_id,
    mmel_item_id: match.mmel_item_id,
    ata_chapter: melItem?.ata_chapter || '',
    item_number: melItem?.item_number || '',
    item_description: melItem?.item_description || '',
    verdict: verdict,
    severity: severity,
    mel_category: melCat,
    mmel_category: mmelCat,
    mel_remarks: melItem?.remarks || '',
    mmel_remarks: mmelItem?.remarks || '',
    requires_hitl_review: requiresHitl,
    hitl_reason: hitlReason
  });
}

// Items MMEL manquants dans MEL
for (const key of data.unmatched_mmel_keys || []) {
  const mmelItem = mmelIndex[key];
  comparisons.push({
    mel_item_id: '',
    mmel_item_id: key,
    ata_chapter: mmelItem?.ata_chapter || '',
    item_number: mmelItem?.item_number || '',
    item_description: mmelItem?.item_description || '',
    verdict: 'MISSING_IN_MEL',
    severity: 'warning',
    mel_category: '',
    mmel_category: mmelItem?.category || '',
    mel_remarks: '',
    mmel_remarks: mmelItem?.remarks || '',
    requires_hitl_review: true,
    hitl_reason: 'MMEL item not found in MEL - verify if equipment installed'
  });
  stats.missing_in_mel++;
  stats.warning++;
  stats.hitl_required++;
}

const total = comparisons.length;
const compliantTotal = stats.compliant + stats.more_restrictive;
const complianceRate = total > 0 ? Math.round((compliantTotal / total) * 10000) / 100 : 0;

return {
  json: {
    run_id: data.run_id,
    audit_timestamp: new Date().toISOString(),
    summary: {
      total: total,
      compliant: stats.compliant,
      more_restrictive: stats.more_restrictive,
      less_restrictive: stats.less_restrictive,
      missing_in_mel: stats.missing_in_mel,
      missing_in_mmel: stats.missing_in_mmel,
      hitl_required: stats.hitl_required,
      compliance_rate: complianceRate
    },
    severity_breakdown: {
      critical: stats.critical,
      high: stats.high,
      medium: stats.medium,
      warning: stats.warning,
      info: stats.info
    },
    comparisons: comparisons
  }
};

// Générer le log HITL
const data = $input.first().json;
const hitlItems = data.comparisons.filter(c => c.requires_hitl_review);

const hitlLog = {
  generated_at: new Date().toISOString(),
  run_id: data.run_id,
  total_items_for_review: hitlItems.length,
  by_severity: {
    critical: hitlItems.filter(i => i.severity === 'critical').length,
    high: hitlItems.filter(i => i.severity === 'high').length,
    medium: hitlItems.filter(i => i.severity === 'medium').length,
    warning: hitlItems.filter(i => i.severity === 'warning').length
  },
  items: hitlItems.map(item => ({
    id: `${item.ata_chapter}-${item.item_number}`,
    verdict: item.verdict,
    severity: item.severity,
    sla_hours: item.severity === 'critical' ? 48 : item.severity === 'high' ? 48 : 24,
    reason: item.hitl_reason,
    mel_data: {
      item_id: item.mel_item_id,
      category: item.mel_category,
      remarks: item.mel_remarks
    },
    mmel_data: {
      item_id: item.mmel_item_id,
      category: item.mmel_category,
      remarks: item.mmel_remarks
    },
    validation: {
      status: 'PENDING',
      decision: null,
      validated_by: null,
      validated_at: null,
      comments: null
    }
  }))
};

return [
  { json: data },
  { json: { hitl_log: hitlLog } }
];

// Générer une alerte pour les écarts critiques
const data = $input.first().json;
const criticalItems = data.comparisons.filter(c => c.severity === 'critical');

return {
  json: {
    alert_type: 'CRITICAL_GAP_DETECTED',
    run_id: data.run_id,
    timestamp: new Date().toISOString(),
    message: `${criticalItems.length} écart(s) critique(s) détecté(s) - Action immédiate requise`,
    sla_deadline: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
    items: criticalItems.map(i => ({
      ata: i.ata_chapter,
      item: i.item_number,
      description: i.item_description,
      issue: i.hitl_reason
    }))
  }
};

// Préparer la réponse finale
const auditData = $('Generate HITL Log').first().json;
const hitlData = $('Generate HITL Log').all()[1]?.json || {};

const response = {
  status: 'completed',
  run_id: auditData.run_id,
  audit_timestamp: auditData.audit_timestamp,
  summary: auditData.summary,
  severity_breakdown: auditData.severity_breakdown,
  hitl_items_count: hitlData.hitl_log?.total_items_for_review || 0,
  recommendations: [],
  output_available: true
};

// Ajouter des recommandations
if (auditData.summary.less_restrictive > 0) {
  response.recommendations.push({
    priority: 'HIGH',
    action: `Review ${auditData.summary.less_restrictive} items where MEL is less restrictive than MMEL`,
    deadline: '48 hours'
  });
}

if (auditData.summary.missing_in_mel > 0) {
  response.recommendations.push({
    priority: 'MEDIUM',
    action: `Verify ${auditData.summary.missing_in_mel} MMEL items not found in MEL`,
    deadline: '1 week'
  });
}

return { json: response };
